(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-nose-sinuses-vignettes-version-2"]={"title":"Nose and Paranasal Sinuses Vignettes 2 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"A 67-year-old man has had sinus symptoms for six months despite treatment. Besides ENT, which other referral is named?","choices":["Dermatology","Cardiology","Allergy, for skin testing","Neurology, for the headache","Rheumatology, for vasculitis"],"answer":2,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 29"},{"q":"A 27-year-old man with a nasal injury has swelling over the bridge, but cannot breathe through the left nostril and the nose looks deviated. What is required?","choices":["Immediate surgery without imaging","Antibiotics and discharge","Nasal packing","Plain nasal radiographs","No imaging"],"answer":3,"exp":"Correct &mdash; two of the four criteria fail, so imaging is needed. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 57"},{"q":"A 39-year-old woman with bacterial sinusitis has a documented anaphylactic reaction to penicillin. Which treatment is appropriate?","choices":["Oseltamivir","Doxycycline","Amoxicillin with clavulanate","Ampicillin with sulbactam","Nystatin"],"answer":1,"exp":"Correct; an antipneumococcal fluoroquinolone such as moxifloxacin is the alternative. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 23"},{"q":"A 42-year-old man with asthma has months of nasal blockage, thick discharge and complete loss of smell. Speculum examination shows grey, glistening masses in both nasal cavities. What is the most likely diagnosis?","choices":["Allergic rhinitis alone","Nasal polyps","Nasopharyngeal carcinoma","Nasal foreign body","Septal haematoma"],"answer":1,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 59"},{"q":"A 19-year-old man struck on the nose during a game has a bulging, boggy swelling on both sides of the nasal septum. What must be done?","choices":["Ice and review in a week","Nasal packing","Oral antibiotics alone","Reassure &mdash; it will resorb","Drainage under anaesthesia"],"answer":4,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 41"},{"q":"A 14-year-old girl with allergic rhinitis is drowsy on her current antihistamine during school. What is the sensible adjustment?","choices":["Double the current dose","Switch to an antibiotic","Start nasal packing","A non-drowsy antihistamine by day","Stop all antihistamines"],"answer":3,"exp":"Correct, keeping the sedating one for night if needed. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 68"},{"q":"A 79-year-old man has frequent winter nosebleeds and a very dry nose. What advice addresses the underlying risk?","choices":["Take daily aspirin","Blow the nose regularly","Use a decongestant spray daily","Sleep flat","Humidify and keep the nose moist"],"answer":4,"exp":"Correct &mdash; chronic dry nose is a named risk factor. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 50"},{"q":"A 52-year-old woman with a nosebleed asks what to do at home. What should she be taught?","choices":["Lie flat and apply ice to the neck","Pack the nostril with tissue and sleep","Pinch for thirty seconds and check repeatedly","Oxymetazoline, then pinch ten minutes","Tilt the head back and pinch the bridge"],"answer":3,"exp":"Correct, sitting up and leaning forward. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 49"},{"q":"A 7-year-old boy has recurrent winter nosebleeds. His mother asks why they keep happening. What is the commonest cause?","choices":["Hypertension","A nasal tumour","Sinus infection","Trauma from his own finger","An underlying bleeding disorder"],"answer":3,"exp":"Correct, with chronic dry nose as a risk factor. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 45"},{"q":"A 50-year-old man is about to have nasal polyps removed and asks whether this is permanent. What should he be told?","choices":["Temporary &mdash; they recur","Surgery is curative in almost all patients","They will return within days","They may become cancerous if not removed","His sense of smell will never return"],"answer":0,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 60"},{"q":"A 71-year-old woman on apixaban has prolonged heavy epistaxis. Which investigations are appropriate?","choices":["Clotting study, crossmatch and count","No blood tests at all","A full blood count only","Computed tomography of the sinuses","Nasal swab culture"],"answer":0,"exp":"Correct &mdash; the clotting study is indicated because she is anticoagulated. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 49"},{"q":"A 54-year-old man is diagnosed with nasopharyngeal carcinoma. How does incidence differ between the sexes?","choices":["Ten times higher in males","It occurs only in males","Two to threefold higher in males","Equal in both","Twice as high in females"],"answer":2,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 69"},{"q":"A 38-year-old man is being referred for persistent sinus disease. What does the lecture require you to tell him?","choices":["Nothing until the specialist has seen him","Only the likely prognosis","Diagnosis, cause, treatment and referral","Only the name of the diagnosis","Only how to take the medicine"],"answer":2,"exp":"Correct &mdash; the four elements named. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 27"},{"q":"A 28-year-old man with facial pressure says it is much worse when he bends to tie his shoes. What does that suggest?","choices":["Dental abscess","Migraine","Temporal arteritis","Sinus involvement","A tension headache"],"answer":3,"exp":"Correct. Sinusitis pain localises to the sinus and worsens bending over or lying flat. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 18"},{"q":"A 30-year-old woman is struck in the face. Besides the nose, which other fractures should be suspected?","choices":["Ankle fracture","Orbital and midface fractures","Rib fractures from the same blow","Clavicle fracture","Wrist fracture"],"answer":1,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 56"},{"q":"A 26-year-old woman has sneezing and a runny nose every spring. Both nostrils show clear discharge and the mucosa looks bluish and swollen. What is the most likely diagnosis?","choices":["Allergic rhinitis","Acute bacterial sinusitis","Nasal foreign body","Nasal polyps","Septal perforation"],"answer":0,"exp":"Correct &mdash; the bluish, oedematous mucosa with bilateral clear discharge. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 67"},{"q":"A 16-year-old girl has sinusitis symptoms during an influenza outbreak and tests positive for influenza. What treatment is appropriate?","choices":["Amoxicillin with clavulanate","An antifungal","Immediate ENT referral","Nasal packing","Oseltamivir for five days"],"answer":4,"exp":"Correct &mdash; indicated in anyone over thirteen. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 24"},{"q":"A 15-year-old boy has three days of congestion and mild facial pressure after a cold, with no fever and no reproducible tenderness. What is appropriate?","choices":["ENT referral","Oral steroids","Symptomatic treatment","Oral antibiotics","Sinus imaging"],"answer":2,"exp":"Correct. Most episodes are viral and settle without antibiotics. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 22"},{"q":"A 55-year-old woman with large nasal polyps has lost her sense of smell. What is that symptom called?","choices":["Hyposmia","Halitosis","Rhinorrhoea","Epistaxis","Anosmia"],"answer":4,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 60"},{"q":"A 3-year-old girl has three weeks of foul-smelling purulent discharge from the right nostril only. The left side is clear and she is afebrile. What is the most likely diagnosis?","choices":["Acute bacterial sinusitis","Allergic rhinitis","Nasal polyps","Deviated septum","A nasal foreign body"],"answer":4,"exp":"Correct &mdash; unilateral foul discharge in a young child strongly suggests it. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 54"},{"q":"A 34-year-old man with asthma and nasal polyps has pansinusitis, and thick mucus with the consistency of peanut butter is removed at surgery. What is the diagnosis?","choices":["Nasopharyngeal carcinoma","Septal perforation","Allergic fungal sinusitis","Chronic bacterial sinusitis","Acute viral rhinosinusitis"],"answer":2,"exp":"Correct &mdash; the eosinophil-laden mucus is characteristic. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 30"},{"q":"A 17-year-old rugby player has an undrained septal haematoma. What is the concern?","choices":["Permanent anosmia","Hearing loss","Malignant change","Chronic sinusitis","Cartilage damage"],"answer":4,"exp":"Correct &mdash; the collection separates cartilage from its blood supply. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 41"},{"q":"A 71-year-old woman has had sinus symptoms for eleven days with unrelenting purulent discharge and left cheek tenderness. What does this suggest?","choices":["Nasal polyps","Bacterial sinusitis","Viral rhinosinusitis","Allergic rhinitis","A nasal foreign body"],"answer":1,"exp":"Correct &mdash; over ten days, purulent, and unilaterally tender. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 16"},{"q":"A 5-year-old has a smooth round bead high in the nasal cavity that cannot be grasped. Which instruments suit that object?","choices":["A wire loop or suction","Tobey or bayonet forceps","An ear curette only","A nasal speculum alone","Irrigation with saline"],"answer":0,"exp":"Correct &mdash; those handle nongraspable round or smooth objects. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 55"},{"q":"A 22-year-old man has a nasal fracture after an assault. Which associated injury must be actively excluded before he goes home?","choices":["Nasal polyps","Allergic rhinitis","Chronic sinusitis","A septal haematoma","A perforated septum"],"answer":3,"exp":"Correct &mdash; nasal fractures are associated with them, and it needs draining. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 56"},{"q":"A 33-year-old woman has a septal perforation. She has used an intranasal steroid daily for years. What is the likely mechanism?","choices":["Barotrauma","Chronic ischaemia","Direct bacterial invasion","An allergic reaction to the propellant","Autoimmune destruction"],"answer":1,"exp":"Correct &mdash; the same mechanism as cocaine use. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 37"},{"q":"A 41-year-old woman with facial pressure has no tenderness when the maxillary and frontal areas are pressed. How does that help?","choices":["It indicates a foreign body","It argues against bacterial infection","It confirms bacterial infection","It confirms a fungal cause","It rules out sinus disease entirely"],"answer":1,"exp":"Correct &mdash; that pain is reproducible on palpation; a common cold's is not. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 18"},{"q":"A 3-year-old boy has a bead visible in the right nostril and is becoming distressed by attempts to look. What is appropriate?","choices":["A course of antibiotics","Reassurance and review in a month","Refer to ENT","Blind sweeping with forceps","Irrigation of the nostril"],"answer":2,"exp":"Correct &mdash; get help rather than risk pushing it deeper. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 54"},{"q":"A 35-year-old man with a deviated septum has obstructive sleep apnoea and recurrent nosebleeds. What is the definitive treatment?","choices":["Septoplasty","Long-term intranasal steroids","Nasal packing","Antihistamines","Continuous positive airway pressure alone"],"answer":0,"exp":"Correct, performed by an otorhinolaryngologist. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 32"},{"q":"A 68-year-old man has years of one-sided blockage and loud snoring. Examination shows the septum pushed to the left. What is the diagnosis?","choices":["Deviated septum","Septal perforation","Nasal polyps","Allergic rhinitis","Chronic sinusitis"],"answer":0,"exp":"Correct. — hughie Nose & Paranasal Sinuses fall 2026.pptx, Slide 32"}]};
